import{_ as e,o,c as r,a2 as a}from"./chunks/framework.D66Xq0Kv.js";const p=JSON.parse('{"title":"VideoDevour · 把视频变成知识库","description":"","frontmatter":{},"headers":[],"relativePath":"projects/videodevour.md","filePath":"projects/videodevour.md","lastUpdated":1791119045000}'),d={name:"projects/videodevour.md"};function i(n,t,l,s,u,h){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="videodevour-·-把视频变成知识库" tabindex="-1">VideoDevour · 把视频变成知识库 <a class="header-anchor" href="#videodevour-·-把视频变成知识库" aria-label="Permalink to &quot;VideoDevour · 把视频变成知识库&quot;">​</a></h1><blockquote><p><a href="https://github.com/datawhalechina/video-devour" target="_blank" rel="noreferrer">datawhalechina/video-devour</a> ⭐156 · <a href="https://github.com/datawhalechina/DOPMC/issues/368" target="_blank" rel="noreferrer">项目立项记录</a> · 我的角色：<strong>第一贡献者</strong>（35 commits，13 个 PR 全部合并）</p></blockquote><h2 id="项目定位" tabindex="-1">项目定位 <a class="header-anchor" href="#项目定位" aria-label="Permalink to &quot;项目定位&quot;">​</a></h2><p>&quot;吃掉视频，输出一份图文并茂的报告。&quot;——基于 <strong>ASR + VLM</strong> 技术的智能视频笔记工具：语音识别生成文本，LLM 提取章节结构，视觉模型挑选关键帧，最终产出带层级、有画面、有依据的结构化报告。</p><p>我对它的最终想象是一个<strong>知识基建工具</strong>：真正优质的 learning 材料往往在视频里（课程、技术分享、访谈、Talk），但&quot;看完以后很难再次利用&quot;。VideoDevour 要做的是把这些内容<strong>提取出来、组织起来、沉淀下来，并且能够二次使用</strong>——放进知识库、生成思维导图与知识图谱、在需要时重新调用。</p><h2 id="核心能力" tabindex="-1">核心能力 <a class="header-anchor" href="#核心能力" aria-label="Permalink to &quot;核心能力&quot;">​</a></h2><ul><li><strong>多信源接入</strong>：B站、YouTube、抖音、微信视频号链接或分享文案 + 本地上传，统一进入&quot;先预览、再下载、后沉淀&quot;的链路</li><li><strong>两种整理速度</strong>：已有字幕的视频直接生成&quot;字幕笔记&quot;（不下载、不做 ASR）；需要完整沉淀时走全链路生成图文报告</li><li><strong>一份报告多种读法</strong>：图文大纲 / 精简报告 / 详细报告之外，可按需生成量子速读、公众号文章、小红书笔记、学习卡片、思维导图、知识图谱</li><li><strong>本地知识库</strong>：所有结果沉淀在本地，同一视频保留 V1/V2 版本，支持按标题、关键词或&quot;记得的观点&quot;检索，整库导出</li><li><strong>桌面客户端</strong>：pywebview 桌面壳 + 本地 FastAPI 服务，把&quot;配置 Python、FFmpeg、模型依赖&quot;的开发环境题变成普通用户可用的界面步骤</li></ul><h2 id="我的工程贡献-桌面客户端从-0-到-1" tabindex="-1">我的工程贡献（桌面客户端从 0 到 1） <a class="header-anchor" href="#我的工程贡献-桌面客户端从-0-到-1" aria-label="Permalink to &quot;我的工程贡献（桌面客户端从 0 到 1）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方向</th><th>代表性 PR</th></tr></thead><tbody><tr><td>架构</td><td>feat: 桌面客户端（macOS/Windows）+ 轻量包与运行时路径改造</td></tr><tr><td>macOS</td><td>支持 Intel (x86_64) 构建；修复 Gatekeeper 判&quot;已损坏&quot;（artifact 丢 symlink）</td></tr><tr><td>Windows</td><td>卡死修复；Cookie 读取 + 应用内登录读取 + 使用指南；下载附件白屏修复</td></tr><tr><td>性能</td><td>衍生文体改为并行生成，修复阻塞事件循环的线程池用法</td></tr><tr><td>发版</td><td>0.1.1 → 0.1.3 → 0.1.6 → 0.1.7 → 0.1.8 连续六个版本</td></tr></tbody></table><h2 id="测试工作" tabindex="-1">测试工作 <a class="header-anchor" href="#测试工作" aria-label="Permalink to &quot;测试工作&quot;">​</a></h2><p>撰写《VideoDevour 长程任务完整测试》：以 3Blue1Brown 长视频为案例做全链路验证，覆盖 FunASR Paraformer V2 语音识别与说话人分离、LLM 大纲生成与文本匹配、FFmpeg 自动切片、关键帧去重与 VLM 智能筛选、报告精加工，以及详细报告/精简报告/图文大纲/量子速读/小红书/公众号等多形态导出的质量核对。</p><ul><li><a href="/projects/">返回项目总览</a></li></ul>',12)])])}const g=e(d,[["render",i]]);export{p as __pageData,g as default};
